const gray = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
r = g = b = gray;
}
const [nr, ng, nb] = mapToPalette(r, g, b, palette);
data[i] = nr;
data[i + 1] = ng;
data[i + 2] = nb;
// Track color usage
const colorKey = `${nr},${ng},${nb}`;
const existing = colorCountMap.get(colorKey);
if (existing) {
existing.count++;
